        out.write(str.getBytes()); // TODO is it correct to use the default charset here?
        out.write('\0');
    }

    public ArchiveEntry createArchiveEntry(File inputFile, String entryName)
            throws IOException {
        return new CpioArchiveEntry(inputFile, entryName);
    }

}

